p='helio.cu'
s=open(p).read()
old=s[s.index('__global__ void k_bc_outer(float* __restrict__ U)'):s.index('__global__ void k_bc_theta')]
new='''__global__ void k_bc_outer(float* __restrict__ U, const float* __restrict__ rc, const float* __restrict__ tc, const float* __restrict__ pc)
{
    int id = blockIdx.x * blockDim.x + threadIdx.x;
    if (id >= P.nt * P.np) return;
    int k = id % P.np + 2, j = id / P.np + 2;
    int is = P.nr + 1;
    size_t s = cid(is, j, k);
    float u[NV], q[NV];
#pragma unroll
    for (int m = 0; m < NV; m++) u[m] = U[m * P.N + s];
    cons2prim(u, P.gam, P.dmin, P.pmin, q);
    float er[3], et[3], ep[3];
    sph_basis(tc[j], pc[k], er, et, ep);
    float br = q[5] * er[0] + q[6] * er[1] + q[7] * er[2];
    float vr = fmaxf(q[1] * er[0] + q[2] * er[1] + q[3] * er[2], 0.f);
    float vt[3] = {q[1] - (q[1] * er[0] + q[2] * er[1] + q[3] * er[2]) * er[0], q[2] - (q[1] * er[0] + q[2] * er[1] + q[3] * er[2]) * er[1], q[3] - (q[1] * er[0] + q[2] * er[1] + q[3] * er[2]) * er[2]};
    for (int g = 0; g < 2; g++) {
        float a = rc[is] / rc[is + 1 + g], a2 = a * a;
        float w[NV];
        w[0] = q[0] * a2;
        w[4] = q[4] * powf(a2, P.gam);
        for (int c = 0; c < 3; c++) {
            w[1 + c] = vr * er[c] + vt[c];
            w[5 + c] = a2 * br * er[c] + a * (q[5 + c] - br * er[c]);
        }
        w[8] = q[8];
        w[9] = q[9];
        float uu[NV];
        prim2cons(w, P.gam, uu);
        size_t c = cid(is + 1 + g, j, k);
#pragma unroll
        for (int m = 0; m < NV; m++) U[m * P.N + c] = uu[m];
    }
}

'''
s=s.replace(old,new)
s=s.replace('''        k_bc_outer<<<nblk(hp.nt * hp.np), TB>>>(U);''','''        k_bc_outer<<<nblk(hp.nt * hp.np), TB>>>(U, d_rc, d_tc, d_pc);''')
open(p,'w').write(s)
